export default [{"level":1,"listening":"Menyimak bunyi, kata, atau instruksi satu langkah dan memberikan respons sederhana.","listening_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","listening_indicators":["Melakukan instruksi satu langkah yang sudah dikenal, seperti ambil bola atau duduk, tanpa contoh gerak dari guru — 4 dari 5.","Menoleh atau menunjuk benda yang disebut namanya di antara beberapa pilihan — 4 dari 5.","Merespons saat namanya dipanggil di tengah kegiatan kelompok."],"listening_key":1,"listening_spiral":"Level 2 menangkap dua kata kunci dalam percakapan sangat pendek. Selama anak masih membaca isyarat tubuh guru, yang terjadi adalah menebak, bukan menyimak bahasa.","speaking":"Menjawab pertanyaan dengan kata, gerak, atau frasa sederhana.","speaking_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","speaking_indicators":["Menjawab pertanyaan pilihan, seperti bola atau buku, dengan kata dan bukan hanya anggukan — 4 dari 5.","Menyebut minimal 5 nama benda tema dengan ucapan yang dapat dipahami guru.","Menyampaikan kebutuhan seperti minum atau ke kamar mandi dengan kata atau frasa, bukan menarik tangan atau menangis, pada dua kesempatan."],"speaking_key":3,"speaking_spiral":"Level 2 menyebutkan benda, tindakan, dan kebutuhan yang dekat dengan diri. Pada indikator kunci inilah bahasa mulai menggantikan isyarat.","reading":"Mengenali 8 huruf vokal/konsonan dan bunyinya; menunjuk huruf sesuai bunyi pada 8 dari 10 percobaan.","reading_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","reading_indicators":["Menunjuk huruf yang benar saat guru menyebutkan bunyinya — 8 dari 10 kartu huruf acak.","Menyebutkan bunyi huruf saat guru menunjuknya — 8 dari 10 huruf yang sudah diperkenalkan.","Memilih benda atau gambar yang berawal bunyi sama dengan huruf yang ditunjuk (b menjadi bola) — 4 dari 5."],"reading_key":3,"reading_spiral":"Level 2 menggabungkan bunyi menjadi suku kata terbuka. Anak yang lolos indikator 1 dan 2 tetapi gagal indikator 3 hafal nama huruf, belum mendengar bunyinya, dan akan macet pada b + a = ba.","writing":"Meniru garis, lingkaran, dan pola; memegang alat tulis dengan aman.","writing_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","writing_indicators":["Memegang pensil dengan jari, bukan genggaman kepal, sepanjang satu kegiatan tanpa diingatkan berulang.","Meniru 4 dari 5 bentuk dasar: garis tegak, garis datar, lingkaran, silang, dan lengkung.","Menelusuri pola tetap di dalam garis batas, keluar jalur tidak lebih dari 2 kali dalam satu lembar."],"writing_key":2,"writing_spiral":"Level 2 menyalin nama sendiri dan 5 kata pendek. Lengkung dan silang adalah bahan pembentuk semua huruf; tanpa keduanya, menyalin nama menjadi kegiatan menggambar.","math":"Menghitung benda 1–5 satu per satu dan mencocokkan jumlah.","math_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","math_indicators":["Menghitung 5 benda sambil menyentuh satu per satu, tanpa terlewat atau terhitung dua kali — 4 dari 5 percobaan.","Menjawab pertanyaan ada berapa dengan menyebut bilangan terakhir, tanpa mengulang hitungan dari awal.","Mencocokkan kartu angka 1–5 dengan kumpulan benda yang jumlahnya sesuai — 4 dari 5."],"math_key":2,"math_spiral":"Level 2 menghitung dan membandingkan sampai 10. Anak yang harus menghitung ulang setiap kali ditanya belum memegang jumlah sebagai satu nilai, sehingga belum dapat membandingkan.","ipas":"Mengamati benda hidup, benda tak hidup, diri, dan keluarga dalam tema terdekat.","ipas_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","ipas_indicators":["Memilah 5 benda ke kelompok hidup dan tak hidup disertai satu alasan sederhana — 4 dari 5.","Menyebutkan anggota keluarga inti dan satu kegiatan yang dilakukan bersama.","Menyampaikan satu hasil pengamatan benda tema berupa warna, bentuk, ukuran, atau permukaan, tanpa diberi pilihan jawaban."],"ipas_key":3,"ipas_spiral":"Level 2 mengenali fungsi pancaindra dan kebiasaan merawat tubuh. Level 2 hanya memberi nama pada indra yang sudah dipakai.","english":"Mengenali dan menirukan 3 kosakata konkret yang muncul dalam tema.","english_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","english_indicators":["Menunjuk gambar atau benda yang benar saat guru menyebut 3 kosakata tema — 3 dari 3 pada dua kesempatan.","Menirukan pengucapan 3 kosakata itu sehingga dikenali guru.","Merespons satu sapaan kelas seperti hello atau thank you dengan kata atau gerak."],"english_key":0,"english_spiral":"English Exposure adalah pengayaan dan tidak menjadi syarat naik level."},{"level":2,"listening":"Menyimak dua kata kunci dalam percakapan atau cerita sangat pendek.","listening_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","listening_indicators":["Menunjuk dua benda yang disebut dalam satu kalimat, misalnya ambil bola dan buku — 4 dari 5.","Menjawab pertanyaan tentang benda dan pemiliknya dari kalimat pendek — 4 dari 5.","Menunggu kalimat selesai sebelum bergerak, bukan langsung berlari begitu kata pertama terdengar — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 3 mengikuti instruksi dua langkah. Anak yang bergerak pada kata pertama tidak pernah mendengar langkah kedua; ia bukan lupa, melainkan belum sempat menerima. Ini soal menahan, bukan soal sikap.","speaking":"Menyebutkan nama benda, tindakan, dan kebutuhan yang dekat dengan diri.","speaking_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","speaking_indicators":["Menyebutkan nama 10 benda tema dan 5 tindakan seperti lari, makan, dan tidur dengan ucapan yang dipahami guru.","Menyampaikan kebutuhannya dengan frasa dua kata seperti mau minum atau sakit perut, pada dua kesempatan.","Memakai kata kerja dan bukan hanya nama benda saat menyampaikan maksud — 4 dari 5."],"speaking_key":3,"speaking_spiral":"Level 3 menyampaikan kalimat, dan kata kerja adalah tulang kalimat. Anak yang hanya menguasai nama benda akan menumpuk kata tanpa pernah sampai ke kalimat.","reading":"Menggabungkan bunyi menjadi suku kata terbuka sederhana pada 8 dari 10 contoh.","reading_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","reading_indicators":["Menggabungkan dua bunyi menjadi suku kata terbuka saat guru menunjuk hurufnya (b–a menjadi ba) — 8 dari 10.","Membaca 10 kartu suku kata terbuka acak seperti ma, si, bu, ke, lo tanpa mengeja ulang lebih dari satu kali — 8 dari 10.","Membaca kata dua suku kata terbuka seperti ma-ma, bu-ku, sa-pi sebagai satu kata, bukan dua potongan yang terpisah — 4 dari 5."],"reading_key":3,"reading_spiral":"Level 3 membaca 10 kata pola sederhana, dan menyatukan dua suku kata menjadi satu kata adalah pintunya. Anak yang lancar pada indikator 1 dan 2 tetapi masih membunyikan bu dan ku sebagai dua benda terpisah belum membaca kata, melainkan membaca suku kata.","writing":"Menyalin nama sendiri dan 5 kata pendek dengan contoh di depan mata, hasilnya dapat dibaca orang lain.","writing_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","writing_indicators":["Menyalin namanya sendiri dengan urutan huruf yang benar dan dapat dibaca orang lain, pada dua kesempatan.","Menyalin 5 kata pendek dari contoh; hurufnya dikenali guru tanpa perlu menebak — 4 dari 5.","Memulai tiap huruf dari titik yang sama dengan arah yang tetap, bukan menggambar bentuknya dari bawah atau terbalik — 8 dari 10 huruf."],"writing_key":3,"writing_spiral":"Level 3 menuntut arah penulisan yang benar. Anak yang menggambar huruf dengan meniru bentuk jadinya bisa terlihat rapi di Level 2, tetapi tulisannya melambat dan berantakan begitu katanya memanjang.","math":"Menghitung dan membandingkan kelompok benda 1–10.","math_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","math_indicators":["Menghitung sampai 10 benda dengan tepat, tanpa terlewat atau terhitung dua kali — 4 dari 5.","Menyebutkan kelompok mana yang lebih banyak dari dua kumpulan yang selisihnya jelas — 4 dari 5.","Membandingkan dua kelompok yang jumlahnya berdekatan, seperti 7 dan 8, dengan menghitung dan bukan menebak dari besar tumpukannya — 4 dari 5."],"math_key":3,"math_spiral":"Level 3 mulai menjumlah. Anak yang masih menilai banyak sedikitnya dari penampakan akan menebak hasil penjumlahan. Indikator ini menguji apakah bilangan sudah mengalahkan tampilan.","ipas":"Mengenali fungsi pancaindra, kebiasaan merawat tubuh, serta aturan aman bersama.","ipas_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","ipas_indicators":["Menyebutkan indra yang dipakainya untuk mengenali suatu benda, misalnya aku tahu ini kasar karena kupegang — 4 dari 5 benda.","Mempraktikkan satu kebiasaan merawat tubuh seperti cuci tangan sebelum makan sampai tuntas tanpa dituntun langkah demi langkah, pada dua kesempatan.","Mengenali benda dengan satu indra saja, misalnya meraba di dalam kantong atau mencium dengan mata tertutup — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 3 mengamati cuaca, dan cuaca tidak bisa dipegang; ia hanya dikenali lewat gabungan tanda. Anak yang belum sadar indra mana memberi informasi apa akan menjawab dari ingatan, bukan dari pengamatan hari itu.","english":"Merespons 3–5 kosakata tema melalui gerak, benda, atau pilihan gambar.","english_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","english_indicators":["Menunjuk atau mengambil benda yang benar untuk 3–5 kosakata tema — 4 dari 5.","Merespons dengan gerak saat mendengar kata yang sudah dikenal, tanpa perlu diterjemahkan.","Ikut serta sampai kegiatan selesai tanpa menarik diri, pada dua kesempatan."],"english_key":0,"english_spiral":"Level 3 mulai merangkai dua kata. Pada tahap ini yang dibangun lebih dulu adalah rasa aman, karena anak yang menolak kegiatan tidak akan mendengar apa pun."},{"level":3,"listening":"Mengikuti instruksi dua langkah dengan bantuan gerak atau gambar.","listening_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","listening_indicators":["Melakukan instruksi dua langkah dengan bantuan gambar atau gerak — 4 dari 5.","Mengulang kembali instruksinya dengan kata-katanya sendiri sebelum mengerjakan — 3 dari 5.","Melakukan kedua langkah dalam urutan yang benar, bukan mengerjakan yang paling diingat lebih dulu — 4 dari 5."],"listening_key":3,"listening_spiral":"Level 4 menyimak cerita, dan cerita adalah rangkaian panjang. Tanpa pegangan pada urutan, yang tertangkap hanya kepingan yang berserak.","speaking":"Menyampaikan kalimat sederhana tentang pengalaman atau hasil pengamatan.","speaking_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","speaking_indicators":["Menyampaikan satu kalimat lengkap dengan pelaku dan tindakan tentang yang baru saja dilakukannya — 4 dari 5.","Menjawab pertanyaan apa yang kamu lihat dengan kalimat, bukan satu kata — 4 dari 5.","Berbicara tentang kejadian yang sudah lewat, bukan hanya yang ada di depan mata — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 4 menceritakan kembali, dan bercerita pada dasarnya adalah berbicara tentang yang tidak sedang terlihat.","reading":"Membaca minimal 10 kata pola sederhana dan membedakan bunyi awal.","reading_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","reading_indicators":["Membaca 10 kata berpola sederhana dengan benar dalam satu kesempatan — 8 dari 10.","Membedakan dua kata yang hanya berbeda bunyi awalnya, seperti buku dan kuku atau sapi dan tapi, dengan menunjuk kata yang disebut guru — 4 dari 5.","Mencocokkan kata yang baru dibacanya dengan benda atau gambarnya — 4 dari 5."],"reading_key":3,"reading_spiral":"Level 4 membaca kalimat pendek dan menjawab pertanyaan siapa atau apa. Kalimat hanya bermakna bila tiap katanya membawa makna. Anak yang melafalkan dengan benar tetapi tidak tahu apa yang dibacanya akan sampai ke ujung kalimat tanpa dapat menjawab satu pun pertanyaan.","writing":"Menulis huruf dan kata sederhana yang didiktekan, tanpa contoh, dengan arah penulisan yang benar.","writing_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","writing_indicators":["Menulis 10 huruf yang disebutkan guru tanpa contoh di depan mata, dengan bentuk yang dapat dibaca — 8 dari 10.","Menulis kata dua suku kata dari contoh dengan huruf lengkap, tidak ada huruf yang hilang — 4 dari 5.","Menulis kata sederhana yang didiktekan, tanpa melihat contoh — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 4 menulis dua kalimat sendiri. Selama anak masih perlu contoh untuk setiap kata, tidak ada sisa tenaga untuk memikirkan isi kalimat.","math":"Menulis angka 0–20 dan menyelesaikan tambah konkret sampai 10.","math_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","math_indicators":["Menulis angka 0–20 yang disebut guru dengan bentuk benar dan tidak terbalik — 8 dari 10.","Menyelesaikan penjumlahan konkret sampai 10 dengan benda — 4 dari 5.","Menjumlah dengan melanjutkan hitungan dari bilangan yang lebih besar, misalnya 5 + 3 menjadi enam, tujuh, delapan, bukan menghitung ulang semuanya dari satu — 3 dari 5."],"math_key":3,"math_spiral":"Level 4 menambah sampai 20. Anak yang selalu mengulang hitungan dari satu kehabisan jari dan waktu begitu melewati 10; melanjutkan hitungan adalah pintunya.","ipas":"Mengamati cuaca dan menjelaskan pengaruhnya terhadap kegiatan keluarga atau kelompok.","ipas_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","ipas_indicators":["Menyebutkan cuaca hari ini beserta dua tanda yang dipakainya untuk tahu, seperti langit mendung dan udara dingin — 4 dari 5 kesempatan.","Menyebutkan satu kegiatan yang berubah karena cuaca, misalnya hujan sehingga bermain di dalam.","Menjelaskannya dengan kata sebab-akibat seperti karena hujan maka, bukan hanya menyebut dua hal berdampingan — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 4 menyelidiki sifat bahan, dan penyelidikan baru berarti bila anak mencari sebab. Anak yang menempelkan dua kejadian tanpa menghubungkannya akan melaporkan hasil percobaan tanpa kesimpulan.","english":"Menggunakan frasa dua kata yang berkaitan dengan tema.","english_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","english_indicators":["Menggunakan frasa dua kata terkait tema, misalnya big ball atau my book — 4 dari 5.","Menirukan frasa baru dengan pelafalan yang dikenali guru.","Memakai frasa itu di luar saat diajarkan, misalnya ketika bermain."],"english_key":0,"english_spiral":"Level 4 menambahkan instruksi kelas dan ungkapan tematik. Frasa yang hanya muncul saat dilatih belum menjadi milik anak; yang dipakai sendiri itulah yang bertahan."},{"level":4,"listening":"Menyimak cerita pendek dan menyebutkan tokoh atau benda utama.","listening_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","listening_indicators":["Menyebutkan tokoh atau benda utama setelah menyimak cerita pendek — 4 dari 5 cerita.","Menjawab satu pertanyaan tentang apa yang terjadi, tanpa melihat gambar — 3 dari 5.","Membedakan tokoh utama dari tokoh yang hanya lewat — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 5 menemukan informasi tersurat, dan menemukan berarti memilih. Anak yang menyebut nama yang terakhir didengar belum memilih. Level 4 adalah akhir Fase Fondasi, jadi kenaikan melewati ujian sumatif.","speaking":"Menceritakan kembali dua peristiwa secara berurutan dengan bantuan gambar.","speaking_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","speaking_indicators":["Menceritakan kembali dua peristiwa dari cerita atau pengalaman dengan bantuan gambar — 4 dari 5.","Memakai kata penanda urutan seperti lalu dan setelah itu minimal sekali dalam satu cerita — 3 dari 5.","Menjaga urutan tetap benar ketika gambarnya diambil — 2 dari 3."],"speaking_key":3,"speaking_spiral":"Level 5 bertanya dan menjawab bergiliran. Dalam percakapan tidak ada gambar yang bisa dipegang. Level 4 adalah akhir Fase Fondasi, jadi kenaikan melewati ujian sumatif.","reading":"Membaca kalimat pendek 3–5 kata dan menjawab pertanyaan siapa/apa.","reading_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","reading_indicators":["Membaca kalimat 3–5 kata dengan berhenti di akhir kalimat, bukan di tengah-tengah — 4 dari 5 kalimat.","Menjawab pertanyaan siapa dan apa dari kalimat yang baru saja dibacanya sendiri — 4 dari 5.","Membaca kalimat maju terus tanpa mengulang dari awal atau mengeja ulang kata yang sudah dilewati — 3 dari 5 kalimat."],"reading_key":3,"reading_spiral":"Level 5 menuntut kelancaran awal pada teks 3–4 kalimat. Anak yang masih mundur dan mengulang kehabisan daya ingat sebelum sampai ke kalimat kedua. Level 4 adalah akhir Fase Fondasi, jadi kenaikan ke Level 5 melewati ujian sumatif.","writing":"Menulis 2 kalimat sederhana dengan spasi dan titik.","writing_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","writing_indicators":["Menulis dua kalimat sendiri tentang satu gambar atau pengalaman, tiap kalimat minimal 3 kata.","Memberi spasi antar kata sehingga tiap kata terpisah jelas — 8 dari 10 kata.","Menutup tiap kalimat dengan titik dan memulainya dengan huruf kapital tanpa diingatkan, dua kalimat berturut-turut pada dua kesempatan."],"writing_key":3,"writing_spiral":"Level 5 menulis paragraf tiga kalimat. Anak yang tidak menandai batas kalimat akan menulis paragraf sebagai satu untaian tanpa henti. Level 4 adalah akhir Fase Fondasi, jadi kenaikan melewati ujian sumatif.","math":"Menyelesaikan tambah-kurang konkret sampai 20 dan menjelaskan strategi.","math_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","math_indicators":["Menyelesaikan tambah dan kurang sampai 20 dengan benda atau gambar — 4 dari 5.","Menjelaskan cara memperoleh jawabannya dengan kata atau peragaan, bukan hanya menyebut hasilnya — 4 dari 5.","Memakai strategi selain menghitung satu per satu, misalnya pasangan sepuluh ketika 8 + 5 dikerjakan sebagai 8 + 2 + 3 — minimal 2 dari 5 soal."],"math_key":3,"math_spiral":"Level 5 masuk ke nilai tempat puluhan. Anak yang hanya menghitung satuan tidak punya dasar untuk melihat sepuluh sebagai satu bundel. Level 4 adalah akhir Fase Fondasi, jadi kenaikan melewati ujian sumatif.","ipas":"Membandingkan sifat bahan serta mempraktikkan kerja sama dan tanggung jawab saat penyelidikan.","ipas_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","ipas_indicators":["Membandingkan dua bahan berdasarkan satu sifat yang disepakati, seperti kasar dan halus atau menyerap air dan tidak, lalu menyampaikan hasilnya — 4 dari 5.","Menjalankan perannya dalam penyelidikan kelompok sampai selesai dan merapikan alat setelahnya, pada dua kesempatan.","Menguji dua bahan dengan perlakuan yang sama, misalnya jumlah air sama dan waktu sama, sebelum menyimpulkan mana yang lebih menyerap — 2 dari 3 penyelidikan."],"ipas_key":3,"ipas_spiral":"Level 5 menuntut perbandingan adil: tanaman disiram dan tidak disiram, selebihnya sama. Anak yang mengubah dua hal sekaligus tidak akan tahu mana penyebabnya. Level 4 adalah akhir Fase Fondasi, jadi kenaikan melewati ujian sumatif.","english":"Mengikuti satu instruksi kelas dan mengucapkan satu ungkapan tematik.","english_criteria":"Terlihat dalam dua kegiatan berbeda; catat ketepatan dan bantuan yang masih dibutuhkan.","english_indicators":["Mengikuti satu instruksi kelas seperti sit down atau line up tanpa contoh gerak — 4 dari 5.","Mengucapkan satu ungkapan tematik pada saat yang tepat.","Bertanya arti kata yang tidak dipahaminya."],"english_key":0,"english_spiral":"Level 5 masuk ke pola tanya jawab dalam permainan. Anak yang berani bertanya arti akan tumbuh jauh lebih cepat daripada yang diam lalu menebak."},{"level":5,"listening":"Menemukan informasi tersurat dari percakapan atau teks lisan pendek.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menjawab pertanyaan tentang informasi yang disebutkan jelas dalam teks lisan — 4 dari 5.","Meminta pengulangan atau bertanya ketika ada bagian yang tidak tertangkap, pada dua kesempatan.","Menjawab dari apa yang didengar hari itu, bukan dari pengetahuan umum yang sudah dimilikinya — 4 dari 5."],"listening_key":3,"listening_spiral":"Level 6 mengurutkan peristiwa yang disimak. Anak yang mencampurkan pengetahuan lama akan mengikuti urutan cerita yang sudah ia kenal. Ini kembaran simpul Membaca Level 5.","speaking":"Bertanya dan menjawab secara bergiliran menggunakan kalimat yang jelas.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Mengajukan pertanyaan yang berkaitan dengan yang sedang dibicarakan — 4 dari 5 percakapan.","Menunggu giliran dan tidak memotong pembicaraan orang lain, pada dua kesempatan.","Menjawab pertanyaan yang ditanyakan, bukan berpindah ke cerita yang ingin ia ceritakan — 4 dari 5."],"speaking_key":3,"speaking_spiral":"Level 6 menceritakan pengalaman dengan awal, kejadian, dan akhir. Anak yang melompat ke cerita lain tidak akan mampu menjaga satu cerita tetap utuh.","reading":"Membaca teks 3–4 kalimat dengan kelancaran awal dan menemukan informasi tersurat.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Membaca teks 3–4 kalimat tanpa berhenti lama di tengah kalimat — 4 dari 5 kalimat terbaca utuh.","Menemukan jawaban yang tertulis jelas dalam teks, seperti siapa, kapan, dan di mana — 4 dari 5.","Menunjukkan bagian teks tempat jawabannya berada, bukan menjawab dari ingatan atau pengalaman sendiri — 4 dari 5."],"reading_key":3,"reading_spiral":"Level 6 menceritakan kembali isi bacaan. Anak yang menjawab dari pengalaman akan menceritakan versinya sendiri dan bukan isi teksnya. Kebiasaan kembali ke teks menopang seluruh fase sampai Fase C.","writing":"Menulis paragraf 3 kalimat tentang pengalaman atau benda.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis tiga kalimat yang semuanya tentang satu hal yang sama — 4 dari 5 karangan.","Tiap kalimat berdiri lengkap dengan pelaku dan tindakan — 8 dari 10 kalimat.","Kalimat kedua dan ketiga menambah keterangan baru, bukan mengulang kalimat pertama — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 6 menuntut paragraf yang runtut. Tulisan yang hanya mengulang isi tidak punya bahan untuk dirangkai, karena keruntutan mensyaratkan ada yang bergerak maju.","math":"Memahami nilai tempat puluhan dan operasi sampai 100 tanpa menyimpan.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyatakan bilangan dua angka sebagai puluhan dan satuan, misalnya 47 sama dengan 4 puluhan dan 7 satuan — 4 dari 5.","Menjumlah dan mengurang sampai 100 tanpa menyimpan — 4 dari 5.","Menambah 10 pada sebarang bilangan tanpa menghitung satu per satu — 4 dari 5."],"math_key":3,"math_spiral":"Level 6 masuk ke ribuan dan penyimpanan. Anak yang belum melihat puluhan sebagai satu bundel akan menghitung ulang setiap kali, dan tidak akan pernah memahami apa yang terjadi saat menyimpan.","ipas":"Mengidentifikasi bagian dan kebutuhan tumbuhan serta peran manusia dalam merawat lingkungan.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menyebutkan bagian tumbuhan dan fungsinya, misalnya akar menyerap air dan daun membuat makanan — 4 dari 5.","Menjalankan percobaan tanaman disiram dan tidak disiram dengan perlakuan lain yang sama, lalu melaporkan hasilnya.","Menjelaskan apa yang terjadi bila satu kebutuhan dihilangkan berdasarkan hasil pengamatannya sendiri, bukan dugaan — 2 dari 3."],"ipas_key":3,"ipas_spiral":"Level 6 menghubungkan tahap daur hidup dengan habitatnya: kecebong perlu air, katak dewasa tidak. Anak yang belum melihat kebutuhan sebagai syarat hidup akan menghafal urutan gambar tanpa tahu mengapa tempatnya berubah.","english":"Bertanya atau menjawab dengan pola kalimat sangat sederhana dalam permainan tema.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menjawab pertanyaan berpola tetap seperti what is this diikuti it is a — 4 dari 5.","Mengajukan pertanyaan berpola tetap kepada temannya dalam permainan.","Melanjutkan permainan meski salah, tanpa berhenti."],"english_key":0,"english_spiral":"Level 6 memperpanjangnya menjadi dialog terpandu. Kesediaan melanjutkan meski salah adalah syaratnya, sebab dialog berhenti bila setiap kekeliruan dianggap kegagalan."},{"level":6,"listening":"Mengurutkan dua sampai tiga peristiwa setelah menyimak cerita.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Mengurutkan dua sampai tiga peristiwa dari cerita yang disimak — 4 dari 5.","Menyebutkan peristiwa mana yang terjadi lebih dulu bila ditanya secara acak — 4 dari 5.","Menjaga urutan tetap benar pada cerita yang tidak sesuai dugaannya — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 7 membedakan fakta dan pendapat. Menerima isi apa adanya dan bukan yang diharapkan adalah sikap yang sama persis dengan yang dibutuhkan di sana.","speaking":"Menceritakan pengalaman dengan awal, kejadian, dan akhir sederhana.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menceritakan pengalaman dengan awal, kejadian, dan akhir yang jelas — 4 dari 5.","Menyebutkan tempat dan waktu kejadian agar pendengar dapat mengikuti — 3 dari 5.","Memberi keterangan yang dibutuhkan pendengar, tidak mengandaikan pendengar sudah tahu — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 7 menjelaskan cara melakukan sesuatu. Petunjuk hanya berguna bila yang menjelaskan sadar apa yang belum diketahui orang lain.","reading":"Membaca paragraf pendek dan menceritakan kembali urutan kejadian.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menceritakan kembali isi paragraf dengan urutan awal, tengah, dan akhir yang benar — 4 dari 5.","Menyebut kata penanda waktu dalam teks seperti mula-mula, kemudian, dan akhirnya — 3 dari 5.","Menceritakan kembali dengan kalimatnya sendiri, bukan menghafal kalimat teks — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 7 menuntut merumuskan gagasan utama. Anak yang menghafal kalimat tidak dapat merangkum, karena yang dipegangnya bunyi kalimat dan bukan maknanya.","writing":"Menulis paragraf runtut dengan huruf kapital dan tanda titik.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Kalimat-kalimatnya berurutan masuk akal dan tidak melompat — 4 dari 5 karangan.","Memakai huruf kapital di awal kalimat dan pada nama orang, serta titik di akhir — 8 dari 10 kalimat.","Memperbaiki sendiri kapital atau titik yang terlewat saat membaca ulang tulisannya — 3 dari 5 karangan."],"writing_key":3,"writing_spiral":"Level 7 menuntut memilih detail yang relevan, yaitu menilai tulisan sendiri. Memeriksa ulang adalah pintu menuju menyunting.","math":"Menyelesaikan tambah-kurang sampai 1.000 dan menjelaskan nilai tempat.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyatakan bilangan tiga angka sebagai ratusan, puluhan, dan satuan — 4 dari 5.","Menjumlah dan mengurang sampai 1.000, termasuk yang menyimpan — 4 dari 5.","Menjelaskan apa yang terjadi saat menyimpan, yaitu sepuluh satuan ditukar menjadi satu puluhan — 3 dari 5."],"math_key":3,"math_spiral":"Level 7 memperkenalkan perkalian sebagai kelompok yang sama besar. Penukaran sepuluh adalah pengelompokan yang pertama dikenal anak; tanpa memahaminya, perkalian menjadi hafalan tanpa dasar.","ipas":"Mengurutkan daur hidup hewan, menghubungkannya dengan habitat, dan menghargai perbedaan makhluk hidup.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Mengurutkan tahap daur hidup dua hewan berbeda — 4 dari 5.","Menjelaskan bahwa hewan yang berubah bentuk tetap hewan yang sama, dan menghubungkan tahapnya dengan tempat hidup.","Membedakan perubahan yang terjadi sendiri seiring waktu dari perubahan yang terjadi karena ada yang melakukannya — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 7 menyelidiki gaya dan gerak, yaitu perubahan yang disebabkan dorongan atau tarikan. Anak yang menganggap semua perubahan terjadi dengan sendirinya tidak akan mencari penyebabnya.","english":"Menggunakan 5–7 kosakata dan dua ungkapan tematik dalam dialog terpandu.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Memakai 5–7 kosakata tema dalam satu dialog terpandu — 4 dari 5.","Memakai dua ungkapan tematik pada giliran yang tepat.","Menjaga percakapan tetap berjalan dengan isyarat sederhana seperti yes, okay, atau again."],"english_key":0,"english_spiral":"Level 7 meminta deskripsi satu sampai dua kalimat. Kosakata yang sudah dipakai dalam percakapan jauh lebih siap dipakai untuk menjelaskan daripada kosakata yang hanya dihafal."},{"level":7,"listening":"Membedakan fakta sederhana dan pendapat dalam percakapan dekat anak.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyebutkan mana pernyataan yang dapat diperiksa benar salahnya dan mana yang merupakan pendapat — 4 dari 5.","Menyebutkan kata penanda pendapat seperti menurutku, sebaiknya, dan paling enak — 3 dari 5.","Menilai pernyataan berdasarkan bisa tidaknya diperiksa, bukan berdasarkan setuju atau tidak setuju — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 8 mencatat kata kunci dan menjelaskan kembali isi teks lisan. Memilih yang penting harus jujur dan bukan memilih yang disukai.","speaking":"Menjelaskan cara melakukan sesuatu menggunakan urutan yang tepat.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menjelaskan cara melakukan sesuatu dalam urutan langkah yang benar — 4 dari 5.","Memakai kata urutan seperti pertama, lalu, dan terakhir — 4 dari 5.","Tidak melewatkan langkah yang dianggapnya sudah jelas, diuji dengan pendengar yang mengikuti persis seperti yang dikatakan — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 8 menyampaikan pendapat beserta alasan. Anak yang melewatkan langkah juga akan melewatkan alasan, karena keduanya sama-sama dianggap sudah jelas bagi semua orang.","reading":"Menemukan gagasan utama dan dua informasi pendukung dalam teks pendek.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyebutkan gagasan utama teks pendek dalam satu kalimat — 4 dari 5.","Menunjukkan dua kalimat yang mendukung gagasan itu — 4 dari 5.","Membedakan gagasan utama dari rincian yang menarik perhatian — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 8 menyimpulkan sebab dan akibat lintas paragraf. Anak yang tersedot detail yang seru kehilangan rantai sebabnya.","writing":"Menulis deskripsi satu paragraf dengan detail yang relevan.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis deskripsi satu paragraf dengan minimal tiga detail seperti bentuk, warna, ukuran, bunyi, atau rasa — 4 dari 5.","Detailnya khas benda itu, bukan detail umum yang cocok untuk benda apa saja — 4 dari 5.","Membuang satu detail yang tidak berhubungan ketika diminta memeriksa ulang — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 8 menyusun narasi dua paragraf. Memilih apa yang masuk dan apa yang dikeluarkan adalah inti bercerita.","math":"Menguasai perkalian sebagai penjumlahan berulang dan pembagian konkret.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyatakan perkalian sebagai kelompok yang sama besar dengan benda atau gambar — 4 dari 5.","Membagi benda ke dalam kelompok sama besar dan menyebutkan sisanya bila ada — 4 dari 5.","Menjawab perkalian kecil tanpa menghitung ulang satu per satu, minimal untuk 2, 5, dan 10 — 4 dari 5."],"math_key":3,"math_spiral":"Level 8 mengerjakan soal cerita dua langkah. Bila setiap perkalian masih dihitung dari awal, tenaga anak habis di langkah pertama dan langkah kedua tidak terjangkau.","ipas":"Menyelidiki gaya dan gerak serta menyusun aturan penggunaan alat yang aman dan adil.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menunjukkan bahwa dorongan atau tarikan mengubah arah, kecepatan, atau bentuk benda — 4 dari 5 percobaan.","Menyusun bersama kelompok satu aturan pemakaian alat yang aman dan berlaku untuk semua orang.","Meramalkan apa yang akan terjadi sebelum mencoba, lalu membandingkan ramalannya dengan hasilnya — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 8 menelusuri perubahan energi. Anak yang hanya mencoba lalu melihat belum berpikir; meramalkan memaksanya punya penjelasan lebih dulu.","english":"Menyampaikan deskripsi satu sampai dua kalimat tentang benda atau kegiatan tema.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Mendeskripsikan benda tema dalam satu sampai dua kalimat — 4 dari 5.","Memakai kata sifat sederhana seperti big, small, atau red dengan tepat.","Menyusun kalimat dengan urutan kata yang dapat dipahami, meski belum sempurna."],"english_key":0,"english_spiral":"Level 8 menuntut dialog tiga sampai empat giliran, dan kalimat yang sanggup berdiri sendiri adalah bahan bagi tiap giliran itu."},{"level":8,"listening":"Mencatat kata kunci dan menjelaskan kembali isi teks lisan.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Mencatat minimal tiga kata kunci saat menyimak paparan pendek — 4 dari 5.","Menjelaskan kembali isi teks lisan memakai catatannya — 4 dari 5.","Mencatat sambil tetap menyimak, tidak berhenti mendengar saat menulis — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 9 menangkap gagasan pokok dari paparan singkat. Bila menulis memutus menyimak, bagian penting justru hilang pada saat ia mencatatnya. Level 8 adalah akhir Fase A, jadi kenaikan melewati ujian sumatif.","speaking":"Menyampaikan pendapat sederhana beserta satu alasan.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menyampaikan pendapat dengan kalimat yang jelas beserta satu alasan — 4 dari 5.","Alasannya berhubungan dengan pendapatnya dan tidak berpindah topik — 4 dari 5.","Alasannya bisa diperiksa atau dilihat orang lain, bukan sekadar karena ia menyukainya — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 9 mempresentasikan informasi tema. Anak yang alasannya masih sebatas selera belum berbicara berdasarkan informasi. Level 8 adalah akhir Fase A, jadi kenaikan melewati ujian sumatif.","reading":"Menyimpulkan urutan, sebab, dan akibat dari bacaan beberapa paragraf.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyusun urutan kejadian dari teks beberapa paragraf — 4 dari 5.","Menyebutkan sebab dan akibat satu peristiwa dengan menunjuk bukti di dalam teks — 4 dari 5.","Membedakan peristiwa yang terjadi setelah dari peristiwa yang terjadi karena — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 9 membedakan fakta dan pendapat serta menjelaskan bukti. Anak yang menganggap urutan waktu sama dengan sebab akan menerima alasan yang keliru. Level 8 adalah akhir Fase A, jadi kenaikan melewati ujian sumatif.","writing":"Menulis narasi dua paragraf dengan awal, tengah, dan akhir.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis narasi dua paragraf yang memiliki awal, tengah, dan akhir yang jelas — 4 dari 5.","Memakai kata penghubung antar paragraf seperti setelah itu atau keesokan harinya — 3 dari 5.","Paragraf kedua melanjutkan paragraf pertama, bukan mengulang ceritanya dari awal — 4 dari 5."],"writing_key":3,"writing_spiral":"Level 9 menulis ringkasan dengan kata sendiri, yang menuntut memegang satu keseluruhan sekaligus. Level 8 adalah akhir Fase A, jadi kenaikan melewati ujian sumatif.","math":"Menyelesaikan operasi campuran dasar dan soal cerita dua langkah.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyelesaikan soal cerita dua langkah dan menuliskan kedua langkahnya — 4 dari 5.","Mengerjakan operasi campuran dengan urutan yang benar, yaitu kali dan bagi lebih dulu — 4 dari 5.","Menentukan sendiri operasi yang dipakai sebelum berhitung — 3 dari 5."],"math_key":3,"math_spiral":"Level 9 memakai pecahan, pengukuran, dan perkalian dua digit dalam konteks nyata, yang semuanya menuntut memilih operasi pada situasi lebih rumit. Level 8 adalah akhir Fase A, jadi kenaikan melewati ujian sumatif.","ipas":"Mengenali sumber dan perubahan energi serta merancang kebiasaan hemat energi bersama.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menyebutkan sumber energi pada alat sehari-hari dan bentuk energi yang dihasilkannya — 4 dari 5.","Merancang satu kebiasaan hemat energi untuk kelas dan menjalankannya minimal seminggu.","Menelusuri perubahan bentuk energi pada satu alat serta menyatakan energinya berubah bentuk dan bukan hilang — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 9 menyelidiki perubahan zat. Gagasan bahwa sesuatu berubah bentuk tanpa lenyap adalah dasarnya. Level 8 adalah akhir Fase A, jadi kenaikan melewati ujian sumatif.","english":"Melakukan dialog pendek tiga sampai empat giliran dalam konteks tema.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Melakukan dialog tema tiga sampai empat giliran — 4 dari 5.","Menanggapi jawaban lawan bicara, bukan mengulang pertanyaannya.","Memakai ungkapan penyambung sederhana seperti and you atau really."],"english_key":0,"english_spiral":"Level 9 berpindah ke teks. Anak yang sudah terbiasa menangkap giliran lawan bicara lebih siap menangkap isi bacaan."},{"level":9,"listening":"Menemukan gagasan pokok dan informasi pendukung dari paparan singkat.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyebutkan gagasan pokok paparan singkat dalam satu kalimat — 4 dari 5.","Menyebutkan dua informasi pendukungnya — 4 dari 5.","Menangkap gagasan pokok sambil paparan terus berjalan, tidak kehilangan bagian berikutnya — 3 dari 5."],"listening_key":3,"listening_spiral":"Inilah yang membedakan menyimak dari membaca: teks dapat diulang, pembicara tidak. Level 10 menyimpulkan tujuan pembicara, yang sering baru jelas di bagian akhir.","speaking":"Mempresentasikan informasi tema dengan kosakata yang sesuai.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menyampaikan presentasi pendek dengan pembuka, isi, dan penutup — 4 dari 5.","Memakai kosakata tema dengan tepat dan menjelaskan istilah yang mungkin asing bagi pendengar — 4 dari 5.","Menyampaikan informasi yang bisa ditunjukkan sumbernya, bukan yang ia kira-kira sendiri — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 10 menanggapi pendapat orang lain. Menanggapi membutuhkan pijakan; bila isinya karangan sendiri, tanggapan berubah menjadi adu keyakinan.","reading":"Membedakan fakta dan pendapat sederhana serta menjelaskan bukti dari teks.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Memilah pernyataan fakta dan pendapat dalam satu teks — 4 dari 5.","Menyebutkan bukti dalam teks yang mendukung sebuah pernyataan — 4 dari 5.","Menyatakan pendapat penulis dengan kata penulis, terpisah dari pendapatnya sendiri — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 10 membandingkan dua teks, yang mensyaratkan tiap teks dipegang utuh sebagai pendapat siapa. Anak yang mencampurkan suaranya sendiri akan membandingkan dua versi dirinya dan bukan dua teks.","writing":"Menulis ringkasan dengan gagasan utama dan kata sendiri.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Ringkasan memuat gagasan utama tanpa menyalin kalimat teks — 4 dari 5.","Ringkasannya lebih pendek dari aslinya dan maknanya tetap utuh — 4 dari 5.","Membuang contoh dan rincian sehingga tersisa yang pokok — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 10 menyusun teks informatif. Struktur pada dasarnya adalah yang pokok yang ditata; anak yang belum dapat memisahkan pokok dari rincian akan menata semuanya sekaligus.","math":"Menggunakan pecahan sederhana, pengukuran, dan perkalian dua digit dalam konteks.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyatakan pecahan sederhana dengan gambar atau benda dan membandingkan dua pecahan berpenyebut sama — 4 dari 5.","Mengukur panjang atau berat dengan satuan baku dan menuliskan hasilnya — 4 dari 5.","Menjelaskan bahwa pecahan selalu terhadap satu keseluruhan tertentu — 3 dari 5."],"math_key":3,"math_spiral":"Level 10 masuk ke pecahan senilai, dan senilai hanya masuk akal bila keseluruhannya sama. Tanpa gagasan ini, pecahan senilai menjadi aturan mengalikan atas dan bawah yang tidak berarti apa-apa.","ipas":"Menyelidiki perubahan zat dan menghubungkannya dengan kegiatan produksi atau konsumsi setempat.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menyelidiki perubahan wujud dan perubahan zat lewat percobaan sederhana — 4 dari 5.","Menghubungkan satu perubahan zat dengan kegiatan produksi atau konsumsi di sekitarnya.","Membedakan perubahan yang dapat dikembalikan seperti es mencair dari yang tidak seperti kayu terbakar, disertai alasan — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 10 masuk ke ekosistem dan tanggung jawab menjaganya. Anak yang mengira semua perubahan dapat dibalik tidak akan merasakan mendesaknya menjaga lingkungan.","english":"Membaca atau menyimak teks tematik pendek dan menemukan informasi langsung.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menemukan informasi yang disebut langsung dalam teks tematik pendek — 4 dari 5.","Menebak makna kata baru dari gambar atau konteks.","Menandai bagian yang tidak dipahami untuk ditanyakan."],"english_key":0,"english_spiral":"Level 10 meminta tiga kalimat tentang pengalaman. Menerima teks lebih dulu memberi anak kalimat contoh yang dapat ia tiru lalu ubah."},{"level":10,"listening":"Menyimpulkan pesan serta tujuan pembicara dari teks lisan.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyebutkan pesan utama pembicara — 4 dari 5.","Menyebutkan tujuan pembicara, yaitu memberi tahu, mengajak, atau menghibur — 4 dari 5.","Menyimpulkan tujuan dari isi dan cara penyampaiannya, bukan dari siapa yang berbicara — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 11 membandingkan dua paparan. Membandingkan hanya jujur bila yang ditimbang isinya dan bukan orangnya.","speaking":"Menanggapi pendapat orang lain secara santun dan relevan.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menanggapi dengan menyebut bagian mana dari pendapat orang lain yang ditanggapi — 4 dari 5.","Menyampaikan ketidaksetujuan tanpa merendahkan orangnya — 4 dari 5.","Menyebutkan ulang pendapat lawan bicara dengan benar sebelum menanggapinya — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 11 menyusun pendapat dengan dua alasan. Alasan sekuat apa pun sia-sia bila yang dijawab bukan pendapat orang itu.","reading":"Membandingkan dua teks bertema sama dan membuat simpulan berbasis bukti.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyebutkan satu persamaan dan satu perbedaan isi dari dua teks bertema sama — 4 dari 5.","Membuat simpulan dan menunjuk bukti dari kedua teks — 4 dari 5.","Menyimpulkan dari kedua teks, bukan hanya dari teks yang lebih mudah atau lebih ia sukai — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 11 menganalisis sebab-akibat dan makna kata berdasarkan konteks, yang menuntut membaca seluruh lingkungan kalimat dan bukan potongan yang nyaman.","writing":"Menulis teks informatif terstruktur dengan judul dan paragraf.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis teks informatif dengan judul yang sesuai isi dan minimal dua paragraf — 4 dari 5.","Tiap paragraf membahas satu hal dan tidak bercampur — 4 dari 5.","Menyusun urutan paragraf menurut kebutuhan pembaca, bukan menurut urutan ia menemukan bahannya — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 11 menuntut revisi. Menata tulisan untuk pembaca adalah bentuk pertama dari menulis ulang demi orang lain.","math":"Menyelesaikan pecahan senilai, desimal awal, dan soal multi-langkah.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menunjukkan dua pecahan senilai dengan gambar atau pembagian yang sama — 4 dari 5.","Menuliskan pecahan sederhana sebagai desimal dan sebaliknya — 4 dari 5.","Menyatakan bahwa setengah, nol koma lima, dan gambar setengah adalah satu nilai yang sama dalam tiga bentuk — 3 dari 5."],"math_key":3,"math_spiral":"Level 11 menambahkan persen sebagai bentuk keempat. Bila ketiga bentuk sebelumnya belum menyatu menjadi satu nilai, persen hanya menjadi hafalan aturan baru.","ipas":"Menjelaskan rantai makanan, keseimbangan ekosistem, dan tanggung jawab warga menjaganya.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menyusun rantai makanan dari satu ekosistem setempat — 4 dari 5.","Menyebutkan satu tindakan warga yang menjaga atau merusak keseimbangan ekosistem itu.","Meramalkan apa yang terjadi pada bagian lain rantai makanan bila satu bagian berkurang — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 11 memandang tubuh sebagai sistem, dengan gagasan yang sama: mengubah satu bagian menggoyang bagian lain.","english":"Menulis atau mengucapkan tiga kalimat terkait pengalaman dalam tema.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menyampaikan atau menulis tiga kalimat tentang pengalamannya dalam tema — 4 dari 5.","Memakai kata kerja bentuk sederhana dengan cukup tepat.","Ketiga kalimatnya berhubungan satu sama lain."],"english_key":0,"english_spiral":"Level 11 membandingkan dua hal, yang menuntut dua kalimat dijajarkan. Kemampuan menyusun beberapa kalimat yang saling berhubungan diperlukan lebih dulu."},{"level":11,"listening":"Membandingkan informasi dari dua paparan lisan bertema sama.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyebutkan persamaan dan perbedaan isi dua paparan bertema sama — 4 dari 5.","Menyebutkan bagian mana yang saling bertentangan — 3 dari 5.","Menahan penilaian sampai kedua paparan selesai didengar — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 12 mengikuti diskusi, tempat banyak suara datang bergantian. Anak yang sudah memutuskan sejak pembicara pertama hanya mendengar sisanya sebagai gangguan.","speaking":"Menyampaikan pendapat dengan dua alasan atau bukti pendukung.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menyampaikan pendapat dengan dua alasan yang berbeda — 4 dari 5.","Menyebutkan bukti atau contoh untuk minimal satu alasannya — 4 dari 5.","Kedua alasannya berdiri sendiri, bukan satu alasan yang diulang dengan kata lain — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 12 merangkum diskusi, yang menuntut melihat mana alasan yang benar-benar berbeda dan mana yang sama tetapi berbaju lain.","reading":"Menganalisis hubungan sebab-akibat dan makna kata berdasarkan konteks.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menjelaskan hubungan sebab dan akibat antar bagian teks dengan menunjuk penanda atau bukti — 4 dari 5.","Menebak makna kata baru dari kalimat sekitarnya, lalu memeriksanya — 4 dari 5.","Mengubah tebakan maknanya ketika kalimat berikutnya tidak cocok — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 12 membaca yang tersirat, yang mensyaratkan kesediaan merevisi tafsir sendiri. Membaca pada tingkat ini adalah menduga lalu bersedia salah.","writing":"Menulis narasi dengan dialog, urutan logis, dan revisi sederhana.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis narasi dengan dialog yang memakai tanda petik dan baris yang benar — 4 dari 5.","Urutan kejadiannya logis dan tidak melompat — 4 dari 5.","Memperbaiki satu bagian yang membingungkan setelah mendapat tanggapan pembaca — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 12 menulis eksposisi. Merevisi karena tanggapan orang lain adalah latihan pertama menulis untuk meyakinkan, bukan sekadar menyampaikan.","math":"Menggunakan pecahan, desimal, persen, dan pengukuran dalam masalah nyata.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyelesaikan masalah sehari-hari yang memuat pecahan, desimal, atau persen — 4 dari 5.","Mengubah antar bentuk sesuai kebutuhan soal — 4 dari 5.","Memilih bentuk yang paling memudahkan soal itu, bukan selalu memakai satu bentuk yang dihafal — 3 dari 5."],"math_key":3,"math_spiral":"Level 12 menuntut strategi yang efisien. Memilih bentuk bilangan adalah wujud paling awal dari memilih strategi.","ipas":"Menghubungkan sistem tubuh dengan kebiasaan sehat, hak memperoleh lingkungan sehat, dan tanggung jawab diri.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menghubungkan satu sistem tubuh dengan kebiasaan yang mempengaruhinya — 4 dari 5.","Menyebutkan satu hak atas lingkungan sehat dan satu tanggung jawab yang menyertainya.","Menjelaskan akibat yang tidak langsung terlihat, misalnya kebiasaan hari ini terhadap kesehatan bulan depan — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 12 menyelidiki cahaya dan bunyi, yang bekerja lewat proses tak terlihat mata. Anak yang hanya percaya pada akibat seketika akan menerima gejalanya begitu saja.","english":"Membandingkan dua objek atau keadaan menggunakan kosakata tema.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Membandingkan dua benda atau keadaan dengan kosakata tema — 4 dari 5.","Memakai bentuk pembanding sederhana seperti bigger atau faster — 3 dari 5.","Menyebutkan dasar perbandingannya, misalnya ukuran, warna, atau jumlah."],"english_key":0,"english_spiral":"Level 12 menceritakan urutan proses. Menyebut dasar perbandingan melatih anak menjelaskan alasan dan bukan hanya menyebut hasil."},{"level":12,"listening":"Mencatat informasi penting dan pertanyaan lanjutan dari diskusi.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Mencatat informasi penting dari diskusi — 4 dari 5.","Menuliskan minimal satu pertanyaan lanjutan yang belum terjawab dalam diskusi — 4 dari 5.","Pertanyaannya menyasar bagian yang belum jelas atau belum dibuktikan — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 13 menilai kecukupan alasan dan bukti dalam presentasi. Mengenali apa yang belum dibuktikan adalah bentuk paling awal dari menakar bukti. Level 12 adalah akhir Fase B, jadi kenaikan melewati ujian sumatif.","speaking":"Memimpin atau merangkum hasil diskusi kelompok kecil.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Merangkum hasil diskusi dengan menyebut pendapat-pendapat yang muncul — 4 dari 5.","Memberi kesempatan bicara kepada anggota yang belum berbicara, pada dua kesempatan.","Rangkumannya memuat pendapat yang berbeda dari pendapatnya sendiri dan disampaikan dengan adil — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 13 menyajikan laporan pengamatan dan menjawab pertanyaan. Anak yang merangkum hanya yang sepihak akan melaporkan pengamatan yang mendukung dugaannya saja. Level 12 adalah akhir Fase B, jadi kenaikan melewati ujian sumatif.","reading":"Menilai informasi tersurat dan tersirat dari teks narasi maupun informasi.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Membedakan informasi yang tertulis dari yang ia simpulkan sendiri — 4 dari 5.","Menyebutkan dasar teks untuk setiap simpulan tersiratnya — 4 dari 5.","Menolak simpulan yang tidak didukung teks meskipun masuk akal atau sesuai pengalamannya — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 13 membandingkan perspektif dan menakar kekuatan alasan. Menakar alasan mensyaratkan sanggup menolak yang sekadar terdengar benar. Level 12 adalah akhir Fase B, jadi kenaikan melewati ujian sumatif.","writing":"Menulis eksposisi dengan klaim, alasan, dan contoh pendukung.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis eksposisi dengan satu klaim yang jelas di awal — 4 dari 5.","Menyertakan minimal dua alasan, masing-masing dengan satu contoh pendukung — 4 dari 5.","Alasannya mendukung klaim yang ia tulis, bukan berpindah ke topik yang lebih ia kuasai — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 13 menulis argumen dengan bukti dan bahasa yang sesuai pembaca. Level 12 adalah akhir Fase B, jadi kenaikan melewati ujian sumatif.","math":"Menyelesaikan operasi bilangan dan geometri dasar dengan strategi efisien.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyelesaikan operasi bilangan dengan strategi yang sesuai dan memeriksa hasilnya — 4 dari 5.","Menghitung keliling dan luas bangun dasar dalam konteks nyata — 4 dari 5.","Memperkirakan hasil sebelum menghitung, lalu memakai perkiraan itu untuk memeriksa jawabannya — 3 dari 5."],"math_key":3,"math_spiral":"Level 13 masuk ke rasio, skala, persen, dan data, wilayah tempat kesalahan dapat meleset jauh tanpa terasa. Perkiraan adalah penjaga terhadap jawaban yang mustahil. Level 12 adalah akhir Fase B, jadi kenaikan melewati ujian sumatif.","ipas":"Menyelidiki cahaya dan bunyi serta menjelaskan pemanfaatannya dalam kehidupan dan budaya masyarakat.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menunjukkan lewat percobaan bahwa cahaya merambat lurus dan dapat dipantulkan — 4 dari 5.","Menjelaskan satu pemanfaatan cahaya atau bunyi dalam kehidupan atau budaya setempat.","Menjelaskan bagaimana sesuatu terjadi dan bukan hanya bahwa itu terjadi — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 13 menjelaskan siklus air, cuaca, dan perubahan muka bumi. Siklus hanya dapat dipahami oleh anak yang terbiasa mencari mekanisme. Level 12 adalah akhir Fase B, jadi kenaikan melewati ujian sumatif.","english":"Menceritakan urutan proses sederhana dengan bantuan kata penghubung.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menceritakan urutan proses sederhana dalam tema, misalnya cara membuat sesuatu — 4 dari 5.","Memakai kata penghubung urutan seperti first, then, dan finally — 4 dari 5.","Urutannya benar sehingga pendengar dapat mengikuti."],"english_key":0,"english_spiral":"Level 13 menjelaskan hasil pengamatan dalam paparan pendek. Urutan yang jelas adalah kerangka paling sederhana untuk menyampaikan sesuatu yang panjang."},{"level":13,"listening":"Menilai kecukupan alasan dan bukti dalam presentasi sederhana.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyebutkan klaim utama presentasi dan alasan yang diberikan — 4 dari 5.","Menyebutkan mana alasan yang didukung bukti dan mana yang belum — 4 dari 5.","Memisahkan klaim, alasan, dan bukti dengan tepat, tidak menganggap alasan yang diulang sebagai bukti — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 14 merangkum dengan struktur yang runtut, dan itu hanya mungkin bila strukturnya terdengar. Anak yang menangkap paparan sebagai satu aliran kata akan merangkumnya menjadi potongan acak.","speaking":"Menyajikan laporan pengamatan secara runtut dan menjawab pertanyaan.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menyajikan laporan pengamatan dengan urutan tujuan, cara, hasil, dan simpulan — 4 dari 5.","Menjawab pertanyaan pendengar dengan merujuk datanya — 4 dari 5.","Menjawab bahwa hal itu belum ia periksa ketika memang begitu keadaannya — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 14 berargumentasi dengan bukti yang dapat diperiksa, dan mengakui batas pengetahuan adalah syaratnya. Anak yang merasa harus selalu punya jawaban pada akhirnya akan mengarang bukti.","reading":"Membandingkan perspektif dan mengevaluasi kekuatan alasan dalam beberapa sumber.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyebutkan perspektif yang berbeda dari dua sumber atau lebih tentang satu hal — 4 dari 5.","Menilai alasan mana yang lebih kuat dan menyebutkan dasarnya — 4 dari 5.","Menilai kekuatan alasan dari bukti yang menyertainya, bukan dari seberapa yakin penulisnya terdengar — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 14 mengenali bias. Bila nada percaya diri dianggap bukti, bias tidak akan pernah terdeteksi, karena bias paling sering datang justru dengan nada yang paling yakin.","writing":"Menulis argumen sederhana dengan bukti dan bahasa yang sesuai pembaca.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis argumen dengan klaim, minimal dua bukti, dan penutup — 4 dari 5.","Menyesuaikan pilihan kata dengan pembaca yang dituju — 4 dari 5.","Menyebutkan satu keberatan yang mungkin muncul dan menjawabnya — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 14 menulis laporan berbasis data. Menjawab keberatan melatih menulis untuk pembaca yang tidak otomatis setuju, dan sikap itulah yang membuat laporan diisi data alih-alih kesan.","math":"Menggunakan rasio, skala, persen, dan data untuk memecahkan masalah.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyelesaikan masalah rasio dan skala dalam konteks nyata — 4 dari 5.","Membaca dan menafsirkan data dari tabel atau diagram — 4 dari 5.","Memeriksa apakah jawabannya masuk akal terhadap situasinya, misalnya jarak pada peta atau besaran persen — 3 dari 5."],"math_key":3,"math_spiral":"Level 14 masuk ke masalah multi-langkah. Kesalahan pada langkah pertama terbawa sampai akhir tanpa ketahuan bila kewajaran jawabannya tidak pernah diuji.","ipas":"Menjelaskan siklus air, cuaca, perubahan muka bumi, dan dampaknya pada kehidupan masyarakat.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Menjelaskan siklus air dengan menyebut tahapan dan penggeraknya, misalnya panas matahari — 4 dari 5.","Menghubungkan satu perubahan muka bumi atau cuaca ekstrem dengan dampaknya pada kegiatan masyarakat — 4 dari 5.","Menjelaskan proses yang berlangsung dalam waktu panjang atau skala luas, bukan hanya yang teramati sekali lihat — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 14 membaca peta Indonesia, yang menuntut membayangkan ruang jauh lebih besar daripada halaman sekolah. Anak yang hanya percaya pada apa yang dapat dilihat langsung tidak akan memahami apa pun yang berskala negara.","english":"Menjelaskan hasil pengamatan tematik dalam paragraf atau paparan pendek.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menjelaskan hasil pengamatan tema dalam satu paragraf atau paparan pendek — 4 dari 5.","Memakai kosakata tema dan istilah sederhana dengan tepat.","Menyampaikan dengan suara dan tempo yang dapat diikuti pendengar."],"english_key":0,"english_spiral":"Level 14 bertukar pendapat dan memberi alasan. Menyampaikan hasil pengamatan melatih berbicara berdasarkan sesuatu yang nyata, dan hal nyata itulah bahan sebuah alasan."},{"level":14,"listening":"Merangkum paparan informatif dengan struktur yang runtut.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Merangkum paparan dengan urutan yang mengikuti struktur aslinya — 4 dari 5.","Rangkumannya memuat gagasan pokok dan dua pendukung utama — 4 dari 5.","Rangkumannya tidak menambahkan hal yang tidak disampaikan pembicara — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 15 mengevaluasi bias. Mengenali tambahan yang datang dari kepalanya sendiri adalah latihan pertama melihat bias, dimulai dari bias sendiri sebelum menilai bias orang lain.","speaking":"Berargumentasi dengan klaim, alasan, dan bukti yang dapat diperiksa.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menyampaikan argumen dengan klaim, alasan, dan bukti yang dapat diperiksa — 4 dari 5.","Menyebutkan dari mana buktinya berasal — 4 dari 5.","Melepaskan atau memperbaiki klaimnya ketika bukti lawan bicara lebih kuat — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 15 menyesuaikan penyampaian dengan pendengar. Anak yang tidak pernah melepaskan klaim akan memakai kemampuan itu untuk memenangkan alih-alih memahamkan; keterampilan yang sama bisa menjadi retorika atau menjadi pengajaran.","reading":"Menyusun simpulan lintas teks dan membedakan fakta, opini, serta bias sederhana.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyusun satu simpulan yang memakai informasi dari minimal dua teks — 4 dari 5.","Memilah fakta, opini, dan bagian yang menunjukkan keberpihakan — 4 dari 5.","Menunjukkan apa yang tidak disebutkan sebuah sumber, bukan hanya menilai yang tertulis — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 15 menganalisis sudut pandang, yang ditentukan juga oleh apa yang dipilih untuk tidak diceritakan. Anak yang hanya menilai yang tertulis melewatkan separuh keputusan penulis.","writing":"Menulis laporan dengan struktur, data, dan penyuntingan mandiri.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis laporan dengan struktur yang jelas: tujuan, cara, hasil, dan simpulan — 4 dari 5.","Menyajikan data dalam tabel atau daftar dan merujuknya di dalam teks — 4 dari 5.","Menyunting sendiri sebelum menyerahkan, dan dapat menunjukkan apa yang ia ubah — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 15 menuntut revisi yang terencana, dan menyunting mandiri adalah bibitnya. Anak yang tidak dapat menyebutkan apa yang ia ubah sebenarnya belum menyunting, baru membaca ulang.","math":"Menyelesaikan masalah multi-langkah yang melibatkan pecahan, desimal, dan bangun.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyelesaikan masalah multi-langkah dan menuliskan tiap langkahnya — 4 dari 5.","Memakai pecahan, desimal, dan bangun dalam satu penyelesaian yang sama — 4 dari 5.","Menemukan sendiri letak kesalahannya ketika hasilnya tidak masuk akal, bukan mengulang semuanya dari awal — 3 dari 5."],"math_key":3,"math_spiral":"Level 15 memodelkan. Model selalu perlu diperbaiki, dan memperbaiki menuntut tahu bagian mana yang keliru alih-alih membuang seluruhnya lalu memulai lagi.","ipas":"Membaca peta Indonesia dan menghubungkan kondisi geografis dengan sumber daya, budaya, serta keberagaman warga.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Membaca peta Indonesia meliputi arah, legenda, dan skala — 4 dari 5.","Menghubungkan kondisi geografis satu daerah dengan sumber daya dan mata pencaharian warganya — 4 dari 5.","Menjelaskan keberagaman budaya sebagai akibat keadaan yang berbeda, bukan sebagai lebih baik atau lebih buruk — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 15 merancang aksi bersama lewat musyawarah. Kesepakatan bersama hanya adil bila perbedaan keadaan diakui sebagai keadaan dan bukan sebagai kekurangan.","english":"Bertukar pendapat dan memberi alasan sederhana dalam konteks tema.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menyampaikan pendapat sederhana dalam bahasa Inggris beserta satu alasan — 4 dari 5.","Menanggapi pendapat teman dengan setuju atau tidak setuju secara santun.","Memakai ungkapan pendapat seperti I think dan because dengan tepat."],"english_key":0,"english_spiral":"Level 15 menyimpulkan teks dan mengajukan pertanyaan lanjutan. Anak yang terbiasa memberi alasan akan bertanya tentang hal yang belum beralasan."},{"level":15,"listening":"Mengevaluasi sudut pandang dan informasi bias dalam teks lisan.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyebutkan sudut pandang pembicara dan kepentingan yang mungkin menyertainya — 4 dari 5.","Menunjukkan pilihan kata yang menandakan keberpihakan — 4 dari 5.","Mengenali bias pada pembicara yang sependapat dengannya, bukan hanya pada yang berseberangan — 3 dari 5."],"listening_key":3,"listening_spiral":"Level 16 mengambil keputusan yang beralasan. Keputusan yang baik menuntut kewaspadaan yang sama ke segala arah; bila hanya pihak lawan yang dicurigai, yang tersisa bukan penilaian melainkan pembelaan.","speaking":"Menyesuaikan gaya, kosakata, dan struktur presentasi dengan pendengar.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Menyesuaikan kosakata dan contoh dengan siapa yang mendengarkan — 4 dari 5.","Mengubah struktur presentasi sesuai waktu dan kebutuhan pendengar — 4 dari 5.","Menyederhanakan tanpa mengubah kebenarannya — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Level 16 memimpin diskusi, yaitu membuat semua orang paham tanpa menyetir isi pembicaraan.","reading":"Menganalisis tema, sudut pandang, dan bukti dari teks kompleks sesuai usia.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyebutkan tema teks dan membedakannya dari topik — 4 dari 5.","Menyebutkan sudut pandang siapa yang dipakai dan bagaimana hal itu mempengaruhi isi — 4 dari 5.","Mendukung tiap penafsirannya dengan kutipan atau bagian teks tertentu — 3 dari 5."],"reading_key":3,"reading_spiral":"Level 16 mensintesis banyak bacaan. Sintesis tanpa jangkar teks berubah menjadi kesan pribadi yang ditulis rapi.","writing":"Menulis teks persuasif dengan tujuan, bukti, dan revisi terencana.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menulis teks persuasif dengan tujuan yang dinyatakan jelas — 4 dari 5.","Menyertakan bukti yang dapat diperiksa, bukan hanya ajakan — 4 dari 5.","Merencanakan revisi sebelum menulis ulang, yaitu menandai apa yang akan diubah dan mengapa — 3 dari 5."],"writing_key":3,"writing_spiral":"Level 16 menuntut karya yang utuh. Karya panjang hanya selesai bila revisinya direncanakan; menunggu ilham menghasilkan tumpukan draf yang tidak pernah jadi.","math":"Menggunakan aljabar awal, data, peluang, dan geometri untuk pemodelan sederhana.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Menyatakan hubungan sederhana dengan lambang atau rumus sebagai aljabar awal — 4 dari 5.","Menafsirkan data dan menyatakan peluang kejadian sederhana — 4 dari 5.","Menyatakan asumsi yang dipakai modelnya dan mengakui batasnya — 3 dari 5."],"math_key":3,"math_spiral":"Level 16 menghadapi masalah kompleks. Mengetahui batas sebuah model adalah yang memisahkan pemecah masalah dari penghitung.","ipas":"Menganalisis penggunaan energi dan merancang aksi musyawarah untuk mengurangi dampak perubahan iklim.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Memperkirakan pemakaian energi di rumah atau kelas dan menyajikan datanya — 4 dari 5.","Menyusun satu rencana aksi bersama lewat musyawarah dan mencatat kesepakatannya.","Menimbang siapa yang terbebani oleh sebuah usulan, bukan hanya apakah usulan itu efektif — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Level 16 menuntut solusi yang adil dan dapat dijalankan bersama. Efektif saja tidak cukup, karena usulan yang menimpakan bebannya kepada satu pihak akan berhenti dengan sendirinya.","english":"Menyimpulkan teks tematik dan mengajukan pertanyaan lanjutan.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Menyimpulkan isi teks tematik dalam satu sampai dua kalimat — 4 dari 5.","Mengajukan satu pertanyaan lanjutan tentang isi teks — 4 dari 5.","Pertanyaannya mengarah pada hal yang belum dijelaskan teks."],"english_key":0,"english_spiral":"Level 16 mempresentasikan proyek dan menanggapi pertanyaan. Anak yang terbiasa menyusun pertanyaan jauh lebih siap menerima pertanyaan."},{"level":16,"listening":"Mensintesis informasi dari diskusi dan paparan untuk membuat keputusan beralasan.","listening_criteria":"Menangkap gagasan dan informasi penting dengan tepat pada minimal 4 dari 5 butir dalam dua kesempatan.","listening_indicators":["Menyatukan informasi dari beberapa pembicara menjadi gambaran yang utuh — 4 dari 5.","Menyebutkan dasar dari keputusan yang ia ambil — 4 dari 5.","Menyebutkan apa yang akan mengubah keputusannya — 3 dari 5."],"listening_key":3,"listening_spiral":"Anak yang lulus ujian sumatif akhir Fase C berstatus Lulus dan siap ke SMP. Dalam menyimak, artinya ia mendengar untuk memutuskan dan bukan untuk menang, serta tahu apa yang akan membuatnya berubah pikiran.","speaking":"Memfasilitasi diskusi, menimbang pandangan berbeda, dan menyampaikan kesimpulan bersama.","speaking_criteria":"Menyampaikan isi secara relevan, runtut, dan dapat dipahami pada dua kesempatan berbeda.","speaking_indicators":["Memfasilitasi diskusi sehingga semua anggota mendapat giliran bicara — 4 dari 5.","Menimbang pandangan yang berbeda dan menyebutkan kekuatan masing-masing — 4 dari 5.","Menyampaikan kesimpulan bersama yang diakui benar oleh pihak yang tadinya berbeda pendapat — 3 dari 5."],"speaking_key":3,"speaking_spiral":"Anak yang lulus ujian sumatif akhir Fase C berstatus Lulus dan siap ke SMP. Dalam berbicara, artinya ia berbicara agar orang lain paham dan dapat memutuskan bersama, bukan agar dirinya menang.","reading":"Mengevaluasi, mensintesis, dan mempresentasikan pemahaman dari beragam bacaan.","reading_criteria":"Menunjukkan minimal 4 dari 5 respons tepat dalam dua sesi berbeda dan dapat menjelaskan jawaban bila diminta.","reading_indicators":["Menyatukan informasi dari tiga sumber atau lebih menjadi satu pemahaman yang runtut — 4 dari 5.","Menyebutkan sumber untuk tiap bagian penting pemahamannya — 4 dari 5.","Menyampaikan di mana sumber-sumber itu tidak sepakat, tidak meratakannya menjadi satu suara — 3 dari 5."],"reading_key":3,"reading_spiral":"Anak yang lulus ujian sumatif akhir Fase C berstatus Lulus dan siap ke SMP. Dalam membaca, artinya ia sanggup menghadapi beberapa sumber sekaligus, menakar mana yang lebih kuat, dan menyampaikan pemahamannya tanpa meratakan perbedaan yang memang ada.","writing":"Menulis karya lengkap yang jelas, koheren, dan disunting mandiri.","writing_criteria":"Memenuhi minimal 3 dari 4 kriteria isi, keruntutan, kosakata, dan kaidah sesuai level pada dua karya berbeda.","writing_indicators":["Menyelesaikan satu karya utuh dari rencana sampai versi akhir — 4 dari 5.","Karyanya koheren, yaitu tiap bagian menopang tujuan yang sama — 4 dari 5.","Menilai karyanya sendiri dengan kriteria yang jelas dan menyebutkan bagian mana yang masih lemah — 3 dari 5."],"writing_key":3,"writing_spiral":"Anak yang lulus ujian sumatif akhir Fase C berstatus Lulus dan siap ke SMP. Dalam menulis, artinya ia sanggup menyelesaikan karya utuh dari rencana sampai versi akhir dan menilai sendiri bagian mana yang masih lemah tanpa menunggu diberi tahu.","math":"Memecahkan masalah kompleks dengan strategi, estimasi, dan pemeriksaan jawaban.","math_criteria":"Menyelesaikan minimal 4 dari 5 tugas setara, menunjukkan strategi, dan memeriksa jawaban dalam dua sesi.","math_indicators":["Memilih strategi yang sesuai untuk masalah yang belum pernah ia temui — 4 dari 5.","Memakai estimasi untuk memeriksa hasil akhirnya — 4 dari 5.","Menjelaskan mengapa strategi itu dipilih, dan mengganti strategi bila jalannya buntu — 3 dari 5."],"math_key":3,"math_spiral":"Anak yang lulus ujian sumatif akhir Fase C berstatus Lulus dan siap ke SMP. Dalam matematika, artinya ia menghadapi masalah yang belum pernah ditemuinya dengan strategi yang dipilih secara sadar, estimasi sebagai penjaga, dan kesediaan mengganti jalan ketika buntu.","ipas":"Merancang penyelidikan, mengolah bukti, dan mengomunikasikan solusi lingkungan yang adil serta dapat dilakukan bersama.","ipas_criteria":"Melakukan pengamatan atau penyelidikan aman, mencatat hasil, dan menyampaikan kesimpulan yang sesuai bukti pada dua kesempatan.","ipas_indicators":["Merancang sendiri satu penyelidikan meliputi pertanyaan, cara, dan data yang dikumpulkan — 4 dari 5.","Mengolah bukti menjadi simpulan yang sesuai data, termasuk ketika hasilnya tidak sesuai dugaan — 4 dari 5.","Mengusulkan solusi yang benar-benar dapat dijalankan oleh orang yang akan menjalankannya — 3 dari 5."],"ipas_key":3,"ipas_spiral":"Anak yang lulus ujian sumatif akhir Fase C berstatus Lulus dan siap ke SMP. Dalam IPAS, artinya ia merancang penyelidikan sendiri, mengikuti bukti termasuk ketika hasilnya tidak menyenangkan, dan mengusulkan tindakan yang adil serta dapat dijalankan bersama.","english":"Mempresentasikan proyek tema serta menanggapi pertanyaan dengan bahasa yang komunikatif.","english_criteria":"Menggunakan atau merespons kosakata dan ungkapan yang menyatu dengan tema pada sedikitnya dua kesempatan, dengan bantuan sesuai level.","english_indicators":["Mempresentasikan proyek tema dalam bahasa Inggris dengan pembuka, isi, dan penutup — 4 dari 5.","Menanggapi pertanyaan pendengar dengan jawaban yang nyambung — 4 dari 5.","Meneruskan penyampaian meski ada kata yang tidak diingat, dengan menjelaskannya memakai kata lain."],"english_key":0,"english_spiral":"English Exposure adalah pengayaan dan tidak pernah menahan kenaikan level maupun kelulusan. Yang dituju bukan kefasihan, melainkan anak yang tidak takut memakai bahasa lain untuk menyampaikan sesuatu yang ia pahami."}];
